#include <stdio.h>

/* 函数原型声明：把函数头抄一遍加上分号。
   函数定义写在 main 之后时，没有这一行，编译器读到 main 里的调用
   就不认识 max_of_two，会报错或给出「隐式声明」警告。 */
int max_of_two(int a, int b);

int main() {
    int a, b, c;
    scanf("%d %d %d", &a, &b, &c);

    /* 把重复的「比大小」交给函数：先比前两个，再用结果和第三个比 */
    int m = max_of_two(a, b);
    m = max_of_two(m, c);

    printf("%d\n", m);
    return 0;
}

/* 函数定义：返回两个整数中较大的那个 */
int max_of_two(int a, int b) {
    if (a > b) {
        return a;   /* return 一执行函数就结束，下面的 return b 不会再跑 */
    }
    return b;
}

