#include <stdio.h>

int is_prime(int n);

int main() {
    int n;
    scanf("%d", &n);

    /* 函数返回 1 或 0，C 里非 0 即为真，所以可以直接当条件用 */
    if (is_prime(n)) {
        printf("yes\n");
    } else {
        printf("no\n");
    }
    return 0;
}

int is_prime(int n) {
    /* 素数从 2 开始：0、1 以及负数都不是素数，先处理掉 */
    if (n < 2) {
        return 0;
    }

    /* 只要找到一个能整除 n 的因子，就能断定它不是素数，
       立刻 return 0 结束函数 —— 这就是「提前返回」 */
    for (int i = 2; i * i <= n; i++) {
        if (n % i == 0) {
            return 0;
        }
    }

    /* 循环走完都没找到因子，说明是素数。
       注意这条路径不能漏，否则函数会返回一个不确定的垃圾值 */
    return 1;
}

tutorial.code:
int is_prime(int n) {
    if (n < 2) {
        return 0;   /* 提前结束，后面的循环根本不会执行 */
    }
    for (int i = 2; i * i <= n; i++) {
        if (n % i == 0) {
            return 0;
        }
    }
    return 1;       /* 所有分支都要有返回值 */
}

if (is_prime(n)) {          /* 非 0 即真 */
    printf("yes\n");
} else {
    printf("no\n");
}

