#include <stdio.h>

void swap_in_function(int x, int y);

int main() {
    int a, b;
    scanf("%d %d", &a, &b);

    /* 这里只是把 a、b 的值各拷贝一份传给函数。
       函数怎么折腾那两份副本，都动不到 a、b 本身。 */
    swap_in_function(a, b);

    printf("函数外: %d %d\n", a, b);
    return 0;
}

/* 形参 x、y 是函数自己的局部变量，函数一返回就消失 */
void swap_in_function(int x, int y) {
    int t = x;
    x = y;
    y = t;

    /* 交换在函数内部确实成功了，所以这一行打印的是交换后的值 */
    printf("函数内: %d %d\n", x, y);
}

