#include <stdio.h>

/* void 表示这个函数不返回任何值，调用它只是「让它去做一件事」 */
void print_stars(int count);

int main() {
    int n;
    scanf("%d", &n);

    /* main 负责决定打几行，每行具体怎么打交给函数。
       n 为 0 时循环一次都不执行，最后只输出总数 0。 */
    int total = 0;
    for (int i = 1; i <= n; i++) {
        print_stars(i);
        /* print_stars 是 void，拿不到它打了几个星号，
           所以星号总数只能在 main 里自己数 */
        total += i;
    }

    printf("%d\n", total);
    return 0;
}

void print_stars(int count) {
    for (int j = 0; j < count; j++) {
        printf("*");
    }
    /* 换行一起放在函数末尾：调用方就不用操心换行这件事了 */
    printf("\n");
}

tutorial.code:
void print_stars(int count) {
    if (count <= 0) {
        return;         /* void 函数可以这样提前结束 */
    }
    for (int j = 0; j < count; j++) {
        printf("*");
    }
    printf("\n");
}

for (int i = 1; i <= n; i++) {
    print_stars(i);     /* 一行一个调用，行数由 i 决定 */
    total += i;
}

