#include <stdio.h>

int factorial(int n);

int main() {
    int n;
    scanf("%d", &n);

    printf("%d\n", factorial(n));
    return 0;
}

int factorial(int n) {
    /* 基准情形（终止条件）：n 为 0 或 1 时直接返回 1，不再递归。
       少了这一句，函数会永远调用下去，把栈耗尽后程序崩溃。 */
    if (n <= 1) {
        return 1;
    }

    /* 递归：n! = n * (n-1)!。每递归一次，参数就小 1，
       规模不断缩小，最终一定会走到上面的基准情形。 */
    return n * factorial(n - 1);
}

tutorial.body:
阶乘的数学定义本身就是递归的：0! = 1，n! = n × (n-1)!。用 C 写出来几乎和公式一模一样：return n * factorial(n - 1);

执行时会一层层往下调用：factorial(3) 需要 factorial(2)，factorial(2) 又需要 factorial(1)。到 factorial(1) 时命中基准情形直接返回 1，然后结果一层层乘回来：1 → 2 → 6。

每一层调用都拥有自己独立的形参 n：factorial(3) 里的 n 是 3，factorial(2) 里的 n 是 2，它们各自活在那一层里，互不干扰。这也是递归能自动「记住」中间状态的原因——靠的不是变量，而是每一层独立的局部变量。

tutorial.code:
int factorial(int n) {
    if (n <= 1) {
        return 1;
    }
    return n * factorial(n - 1);
}

if (n <= 1) {
    return 1;   /* 基准情形：没有它，递归永不停止 */
}

