#include <stdio.h>

/* 全局变量：定义在所有函数外面，任何函数都能直接读写。
   它和局部变量不同 —— 即使不写 = 0，编译器也会自动把它初始化成 0；
   而局部变量不初始化就是内存里的随机值。 */
int call_count = 0;

int fib(int n);

int main() {
    int n;
    scanf("%d", &n);

    int value = fib(n);     /* 算完之后 call_count 里就是调用次数 */

    printf("%d\n", value);
    printf("%d\n", call_count);
    return 0;
}

int fib(int n) {
    call_count++;   /* 每进来一次就记一笔，用来数总共调用了几次 */

    /* 两个基准情形：递推式一次要算两个子问题，
       所以 n 减到 0 和 1 时都得有地方停下来 */
    if (n == 0) {
        return 0;
    }
    if (n == 1) {
        return 1;
    }

    /* 注意这一行会让函数被调用两次，所以调用次数涨得非常快 */
    return fib(n - 1) + fib(n - 2);
}

tutorial.code:
int fib(int n) {
    if (n == 0) return 0;       /* 基准情形一 */
    if (n == 1) return 1;       /* 基准情形二 */
    return fib(n - 1) + fib(n - 2);
}

